"""Distinct service questions, safe first checks and direct, named contacts.

Keep this editorial layer separate from intake, pricing and provider routing.
Provider identity comes from the existing catalogs, not duplicate contact data.
"""
import html
import json
import re
import shutil
from editorial import write_editorial_page
from local_help import PEOPLE

E = html.escape


def link(url, label, cls=''):
    return f'<a class="{cls}" href="{E(url, quote=True)}">{E(label)}</a>'


def section(id, title, body):
    return f'<section class="intent-section" id="{id}"><h2>{title}</h2>{body}</section>'


def faq(items):
    return section('questions', 'A few good questions.', ''.join(
        f'<details><summary>{E(q)}</summary><p>{a}</p></details>' for q, a in items))


def call_card(p, note, booking=None):
    actions = link('tel:'+p['tel'], 'Call '+p['phone'], 'btn primary')
    if booking:
        actions += link(booking, 'Book with Middletown', 'btn outline')
        actions += link('/start/?intent=comfort', 'Send a service request', 'intent-text-link')
    else:
        actions += link('/businesses/'+p['slug']+'/', 'Meet '+p['name'], 'btn outline')
    return ('<article class="intent-contact"><span class="eyebrow">YOUR DIRECT CONTACT</span><h3>'+E(p['name'])+'</h3><p>'+E(note)+'</p><div class="intent-actions">'+actions+'</div><p class="intent-small">'+
        ('No Wazoozie account needed. Online booking opens Housecall Pro. Middletown confirms coverage, charges and the appointment. A service request is not a booking or emergency dispatch.' if booking else 'No Wazoozie account needed. Call the named business or professional to arrange a conversation. Wazoozie does not reserve a time or send this inquiry to another business.')+'</p></article>')


ELECTRICAL_TIPS = '''<section class="intent-section simple-checks" id="simple-electrical-checks" aria-labelledby="electrical-checks-title"><span class="eyebrow">THE EASY THINGS FIRST</span><h2 id="electrical-checks-title">Lights not working? Four simple checks.</h2><p>You do not need to be an electrician to spot an overlooked switch. Stay with ordinary, accessible controls and stop if anything looks or feels unsafe.</p><div class="intent-warning"><strong>Stop before checking:</strong> smoke, sparks, a burning smell, buzzing, heat, exposed wires or water near electrical equipment need professional help. Do not touch the equipment or panel. For fire or immediate danger, leave and call emergency services from safety.</div><ol class="intent-checks"><li><h3>Check the switches.</h3><p>Try the normal wall switch and the lamp’s own switch. For a light controlled from two places, check both. Make sure a dimmer has not simply been turned all the way down.</p></li><li><h3>Check the lamp or bulb.</h3><p>If it is dry, cool and undamaged, check whether a plug-in lamp is fully plugged in. Switch the light off and let the bulb cool before a simple, safely reachable bulb change. Use the fixture’s specified bulb type and maximum wattage; skip hard-to-reach fixtures.</p></li><li><h3>Check how far the outage goes.</h3><p>Is it one lamp, one room or the whole house? Check your utility’s outage information if the whole home is affected. Stay away from downed wires and keep others clear.</p></li><li><h3>Look at the breakers safely.</h3><p>Only approach a dry, intact panel with safe access. Check the labeled breaker positions using the normal front door; never remove the protective cover. If a breaker is tripped, reset it only once if you know the cause, have removed the overload and can follow the panel maker’s instructions. If the cause is unclear, it will not reset or it trips again, leave it off and call an electrician. Never hold a breaker on.</p></li></ol><p class="intent-small">These are basic observations, not a wiring diagnosis. Do not open outlets, switches or light fittings, test live wiring, bypass protection or replace a breaker yourself.</p><p>Still in the dark? '''+link('tel:+14452589962', 'Call Ryan Dugan Electric at 445-258-9962')+''' and describe which lights or rooms are affected.</p></section>'''

FURNACE_TIPS = '''<p>Try these only if there is no gas smell, carbon monoxide alarm, burning smell, smoke, sparking or water around the equipment. For a suspected gas leak or carbon monoxide alarm, leave immediately without operating switches and call emergency services or the utility from a safe place.</p><ol class="intent-checks"><li><h3>Check the thermostat mode.</h3><p>Make sure it is set to Heat and the target temperature is above the room temperature. Check whether an away setting or schedule changed the target. Allow the normal delay described in the thermostat manual.</p></li><li><h3>Check the thermostat batteries.</h3><p>If your model uses homeowner-replaceable batteries and the display is blank or shows a low-battery warning, follow its manual. Do not remove wiring or assume every thermostat uses batteries.</p></li><li><h3>Give the air a clear path.</h3><p>Move furniture, rugs and stored items away from supply registers and return grilles. Note whether one room or the whole house has weak airflow. Leave equipment compartments closed.</p></li><li><h3>Check the filter reminder.</h3><p>Review when the filter was last changed. Replace it only if your manual describes a simple homeowner-accessible filter, using the specified size and type and following its shutdown instructions. If access is unclear, leave it for the technician. Never run the system without its filter.</p></li></ol><p class="intent-small">If heat still does not return, call for service. Do not relight burners, open fuel lines, remove equipment panels, bypass safety controls or repeatedly reset a furnace that stops.</p>'''


def add(out, origin, pages, providers, booking):
    root = out.parent
    shutil.copy(root/'assets/service-intents.css', out/'assets/service-intents.css')
    base = origin or 'http://localhost:8123'
    people = {p['slug']: p for p in PEOPLE}
    hvac, electrician = providers['middletown'], providers['ryan']
    trans = people['trans-man-transmissions-eddystone']
    agents = [p for p in PEOPLE if p['category'] == 'realestate']
    furnace_path = '/services/furnace-repair/'
    panel_path = '/services/electrical-panel-upgrades/'
    trans_path = '/auto-mechanics/transmission-repair/'
    buyer_path = '/real-estate-agents/first-time-home-buyers/'
    booking_url = booking+'&utm_content=services-furnace-repair'

    def render(path, title, desc, eyebrow, heading, intro, parent, parent_label, body, contact, trust):
        trust = trust.replace('Wazoozie is operated by Bryan Cordy, owner of Middletown HVAC. This page promotes his HVAC business.', 'Middletown HVAC is a related Wazoozie business. This page promotes its HVAC services.')
        trust = trust.replace(' Wazoozie’s owner, Bryan Cordy, also owns Middletown HVAC.', '')
        crumbs = '<nav class="breadcrumb" aria-label="Breadcrumb">'+link('/local-help/', 'Local help')+'<span>/</span>'+link(parent,parent_label)+'<span>/</span><span>'+E(title.split(' | ')[0])+'</span></nav>'
        content = '<div class="wrap intent-page">'+crumbs+'<section class="intent-hero"><div><span class="eyebrow">'+E(eyebrow)+'</span><h1>'+heading+'</h1><p class="intent-lede">'+intro+'</p><nav class="intent-jumps" aria-label="On this page">'+link('#first-step','Start here')+link('#questions','Common questions')+link('#contact-options','Contact options')+'</nav></div><aside class="intent-hero-note"><span>THE WAZOOZIE WAY</span><p>A useful answer.<br>A real person to call.<br>You choose what happens next.</p></aside></section><div class="intent-layout"><article>'+body+'</article><aside id="contact-options" class="intent-contact-column">'+contact+'<div class="intent-trust"><h2>Know the connection.</h2>'+trust+'<p>'+link('/how-it-works/','How Wazoozie works')+'</p></div></aside></div></div>'
        write_editorial_page(out,origin,pages,path,title,desc,content)
        target = out/path.strip('/')/'index.html'
        s = target.read_text()
        # Editorial pages inherit the site shell, not its navigation geometry.
        s = s.replace('</head>','<link rel="stylesheet" href="/assets/service-intents.css"></head>',1)
        def breadcrumbs(match):
            data = json.loads(match.group(1))
            for node in data.get('@graph', [data]):
                if node.get('@type') == 'BreadcrumbList':
                    node['itemListElement'] = [
                        {'@type':'ListItem','position':1,'name':'Local help','item':base+'/local-help/'},
                        {'@type':'ListItem','position':2,'name':parent_label,'item':base+parent},
                        {'@type':'ListItem','position':3,'name':title,'item':base+path}]
            return '<script type="application/ld+json">'+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+'</script>'
        s = re.sub(r'<script type="application/ld\+json">(.*?)</script>',breadcrumbs,s,flags=re.S)
        if path == furnace_path:
            dock = link(booking_url,'Book with Middletown','btn primary')+link('tel:'+hvac['tel'],'Call','btn outline')
        elif path in (panel_path,trans_path):
            provider = electrician if path == panel_path else trans
            dock = link('tel:'+provider['tel'],'Call '+provider['name'],'btn primary')+link('/businesses/'+provider['slug']+'/','Profile','btn outline')
        else:
            dock = link('#contact-options','Choose an agent to call','btn primary')+link('/real-estate-agents/','All profiles','btn outline')
        s = re.sub(r'<aside class="contact-dock[^"]*".*?</aside>','<aside class="contact-dock" aria-label="Contact options for this guide">'+dock+'</aside>',s,count=1,flags=re.S)
        target.write_text(s)

    furnace = section('first-step', 'The house is cold. Start with what changed.', '<p>For furnace and no-heat inquiries, Wazoozie connects you directly with Glen Mills-based Middletown HVAC. Its published service menu includes furnaces, heat pumps and heating repairs. Ask the office to confirm your address, equipment and visit type before booking.</p><div class="intent-mini-grid"><div><h3>Nothing starts</h3><p>Note the thermostat display, any visible message and when the heat last worked. Say whether other power in the house is affected.</p></div><div><h3>It runs, then stops</h3><p>Describe the pattern without restarting it repeatedly. A shutdown can be a safety response, so leave the diagnosis to a technician.</p></div><div><h3>Air moves, but feels cool</h3><p>Tell the office whether you have a furnace or heat pump, if known. The equipment type matters; a symptom alone does not identify the repair.</p></div></div>')
    furnace += section('simple-checks','Four simple checks before you call.',FURNACE_TIPS)
    furnace += section('visit','Make the service call count.','<p>A useful message is short: “My furnace stopped heating last night. The thermostat says Heat, the fan runs, and the house is getting colder.” Add your town, equipment type and any displayed message. You do not need to diagnose it first.</p><ul><li>Ask for the diagnostic charge and what the initial visit includes.</li><li>Confirm how repair options and pricing will be approved before work starts.</li><li>Discuss the arrival window and how the appointment is confirmed.</li><li>Tell the office if the home is becoming unsafe for someone; do not rely on an online request for emergency dispatch.</li></ul><p>If you have radiators or baseboards supplied by a boiler, use the <a href="/services/boilers/">boiler-service page</a>. Planning a change rather than a repair? Compare <a href="/services/replacement-estimates/">replacement-estimate questions</a> after an assessment.</p>')
    furnace += faq([('Does a furnace that stops need to be replaced?','Not necessarily. Ask for the diagnostic findings, repair options and the reason for any replacement recommendation. Age or one symptom alone does not establish the right decision.'),('Can I book a no-heat visit online?','The booking button opens Middletown HVAC’s existing Housecall Pro flow. Confirm address coverage, fees and appointment details there or by phone. No same-day or emergency availability is promised.'),('What if I live outside Glen Mills?','Call with your exact address. Middletown is based in Glen Mills; that is not a promise of coverage for every address in Delco, Chester County or the Main Line.')])
    furnace += section('sources','Where the service information comes from.','<p><a href="https://www.mtownhvac.com/services/">Middletown HVAC’s published services</a> and its <a href="/businesses/middletown-hvac/">Wazoozie business profile</a>. The simple checks are general homeowner guidance, not a remote diagnosis. Mention Wazoozie if you call; a link click alone does not establish a completed inquiry.</p>')
    render(furnace_path,'Furnace Repair & No-Heat Help | Middletown HVAC, Glen Mills','Furnace not heating? Try four simple, safe checks, prepare for a diagnostic visit and call Middletown HVAC in Glen Mills at 610-500-6416.','WHEN THE SWEATER IS NOT ENOUGH','Furnace not heating?<br><em>Start with the simple things.</em>','Four safe checks, a clearer service conversation and a direct line to Middletown HVAC.','/services/heating-cooling/','Heating & cooling',furnace,call_card(hvac,'Glen Mills-based heating and cooling business. Confirm your address and current appointment availability.',booking_url),'<p>Wazoozie is operated by Bryan Cordy, owner of Middletown HVAC. This page promotes his HVAC business. <a href="/businesses/middletown-hvac/">Read the profile, sources and published reviews</a>.</p>')

    panel = section('first-step','More power starts with a plan.','<p>Adding equipment or renovating a room can change what you need from your electrical system. Ryan Dugan Electric LLC publishes electrical panel upgrades, repairs, lighting and residential electrical services. Start by describing the project; a panel upgrade should follow an assessment, not a guess from a breaker count.</p><div class="intent-mini-grid"><div><h3>Planning new equipment?</h3><p>Bring the proposed equipment details. Ask the electrician to assess the electrical load, existing service and circuit requirements.</p></div><div><h3>Running out of space?</h3><p>Available breaker spaces and available electrical capacity are different questions. Ask what options fit the existing installation.</p></div><div><h3>Something keeps tripping?</h3><p>A repeated trip needs troubleshooting. Do not assume a larger panel or breaker will fix it, and never replace a breaker with a higher rating yourself.</p></div></div>')
    panel += section('scope','What belongs in the written proposal?','<ol><li><strong>The reason for the work.</strong> Ask what the assessment found and whether the proposal is for a panel replacement, additional circuits or a service upgrade.</li><li><strong>The complete scope.</strong> Confirm which equipment, wiring, grounding or bonding work and finishing repairs are included.</li><li><strong>Permits and coordination.</strong> Ask who handles local permits, inspections and utility involvement if required.</li><li><strong>The outage plan.</strong> Discuss when power would be unavailable and how to plan for refrigeration, work-from-home needs or essential equipment.</li><li><strong>The price and changes.</strong> Get the total scope, payment terms and the approval process for unexpected work in writing.</li></ol><p>For an HVAC conversion, share the proposed equipment requirements with both contractors. Ryan handles Middletown HVAC’s electrical work, as confirmed by Wazoozie’s owner; that does not mean every project is a joint contract.</p>')
    panel += section('safety','A panel is not a weekend experiment.','<div class="intent-warning">Do not remove the protective cover, touch wiring, work inside the panel or bypass a breaker. Water, heat, buzzing, sparks or a burning smell are reasons to stay clear and get professional help. For fire or immediate danger, leave and call emergency services.</div><p>For an ordinary light that stopped working, start with <a href="/services/electrical/#simple-electrical-checks">four simple checks for switches, bulbs, outages and breaker positions</a>. These checks do not establish that your panel needs replacing.</p>')
    panel += faq([('Does a new heat pump automatically mean a new panel?','No. The electrician needs to assess the existing service and the proposed equipment. Ask for the basis of any recommended upgrade before approving it.'),('Can I get a panel price from this page?','This page does not quote your installation. Existing conditions, required work, permits and utility coordination can change the scope. Ask Ryan for a written proposal after assessment.'),('How do I arrange a visit?','Call Ryan Dugan Electric directly at 445-258-9962. Confirm your address, the project, any assessment charge and the appointment. Wazoozie does not show live appointment slots for this business.')])
    panel += section('sources','Read the business details.','<p><a href="https://duganelectric.com/">Ryan Dugan Electric’s official website</a> publishes panel upgrades and residential electrical services. See the <a href="/businesses/ryan-dugan-electric/">Wazoozie profile</a> for its contact information, working relationship and linked review sources. Confirm current credentials and service coverage directly.</p>')
    render(panel_path,'Electrical Panel Upgrade Planning | Ryan Dugan Electric','Planning an electrical panel upgrade in Delco? Review load-assessment, permit and estimate questions, then contact Ryan Dugan Electric at 445-258-9962.','ROOM FOR THE NEXT PROJECT','Planning a panel upgrade?<br><em>Get the whole picture.</em>','The useful questions about capacity, scope and downtime before you agree to electrical work.','/services/electrical/','Electrical',panel,call_card(electrician,'Electrical panel upgrades and repair inquiries. Call to confirm the work, your address and scheduling.'),'<p>Ryan Dugan Electric handles Middletown HVAC’s electrical work. Wazoozie’s owner, Bryan Cordy, also owns Middletown HVAC. Read the <a href="/businesses/ryan-dugan-electric/">business profile</a> and agree on your own scope directly with Ryan.</p>')

    transmission = section('first-step','Describe the drive, not the diagnosis.','<p>A delayed shift, a warning light or a change in how the car moves is a reason to ask for an assessment. It does not establish that the transmission needs rebuilding. Trans Man Transmissions is Wazoozie’s owner-recommended contact in Eddystone for transmission-service inquiries.</p><p>The existing public sources list <strong>1229 Chester Pike, Eddystone, PA 19022</strong> and <strong>610-521-6672</strong>. Confirm the current location, your vehicle and accepted work by phone before visiting. A current official website has not been confirmed.</p><div class="intent-warning">If the vehicle loses drive, behaves unpredictably, has a serious leak or cannot be operated safely, stop in a safe place and arrange appropriate roadside help. Do not keep driving to test a symptom or crawl under a vehicle supported only by a jack.</div>')
    transmission += section('describe','Give the shop a useful starting point.','<ul><li><strong>The vehicle:</strong> year, make, model, mileage and transmission type, if known.</li><li><strong>The change:</strong> delayed engagement, unusual shifting, a new noise or a warning message, in your own words.</li><li><strong>The pattern:</strong> when you first noticed it and whether it happens when starting, accelerating or after the car warms up.</li><li><strong>The history:</strong> relevant repairs, recent service and any written diagnosis you already have.</li></ul><p>You do not need to recreate a problem in traffic. Use what you have already noticed. Ask whether the shop handles your vehicle and whether it should be towed rather than driven in.</p>')
    transmission += section('estimate','Ask these before authorizing the next step.','<ol><li>What does the diagnostic assessment cost and include?</li><li>Does any further inspection or disassembly need separate approval, and what would that cost?</li><li>What findings support the proposed repair, and are there alternatives?</li><li>Which parts and labor are included, and how are additional costs approved?</li><li>What written warranty, exclusions and follow-up requirements apply?</li></ol><p>Keep the estimate and final invoice. If an estimate changes, the <a href="/guides/car-repair-estimate-changed/">car-repair estimate guide</a> helps organize the next conversation. For general maintenance or tires, compare the separate <a href="/auto-mechanics/">auto-repair listings</a>.</p>')
    transmission += faq([('Does a shifting problem always mean transmission replacement?','No. Symptoms can have different causes. Ask the shop for its findings and the reasoning behind the proposed work rather than choosing a repair from a symptom list.'),('Can I book Trans Man on Wazoozie?','Call the published number to ask about scheduling. Wazoozie does not have a live appointment calendar for this shop and does not send your inquiry to Middletown HVAC.'),('How was this shop recommended?','Wazoozie’s owner recommended Trans Man after a good personal experience. Public directories supply the listed contact details. This is not an independent credential inspection or a guarantee of a result.')])
    transmission += section('sources','Check the listing before you travel.','<p>Contact sources: '+', '.join(link(url,label) for label,url in trans['sources'])+'. Read the <a href="/businesses/trans-man-transmissions-eddystone/">full Trans Man profile</a> for the recommendation and source limits. General consumer background: <a href="https://consumer.ftc.gov/articles/0211-auto-repair-basics">FTC auto-repair basics</a>.</p>')
    render(trans_path,'Transmission Repair Inquiries in Eddystone | Trans Man','Prepare a transmission-service inquiry with Trans Man Transmissions in Eddystone. Find the published phone, symptom checklist and diagnostic-fee questions.','WHEN THE DRIVE FEELS DIFFERENT','Transmission trouble?<br><em>Have a better first call.</em>','Know what to describe, what to ask and who you are calling before the keys change hands.','/auto-mechanics/','Auto mechanics',transmission,call_card(trans,'Listed at 1229 Chester Pike, Eddystone. Call to confirm current details, vehicle fit and availability.'),'<p>Recommended by Wazoozie’s owner after a personal experience. Contact details come from linked public directories; a current official website has not been confirmed. This is not an independent license, certification or workmanship inspection.</p>')

    buying = section('first-step','Before the open houses, talk about your plan.','<p>Your first home comes with a lot of new words. Start with a professional who can explain the process, the services they offer and the agreement you would be signing. Wazoozie introduces three owner-recommended real estate professionals; you choose who to contact.</p><p>Caitlin Kerezsi’s public Keller Williams profile specifically mentions first-time buyers. Megan Kerezsi’s profile describes buyer and seller work with The Kerezsi Real Estate Team. Libbi Skivo’s official team profile describes buyer and seller representation in the Philadelphia area. Ask each about your intended location and current availability.</p>')
    buying += section('prepare','Bring a short wish list. Leave room for questions.','<div class="intent-mini-grid"><div><h3>The home</h3><p>List the space, accessibility features, commute and practical needs that matter to you. Separate must-haves from things you could change later.</p></div><div><h3>The timing</h3><p>Explain your lease or move dates and how flexible they are. Ask which steps should happen before you start making offers.</p></div><div><h3>The budget conversation</h3><p>Think about the monthly payment and costs beyond it, including taxes, insurance, maintenance and any association fees. Discuss financing questions with an appropriate lender; an agent introduction is not loan approval.</p></div></div>')
    buying += section('representation','Understand who represents you.','<ul><li>Who would be your main contact, and what does the team handle?</li><li>What services are included before, during and after an offer?</li><li>When is a written representation agreement needed, how long does it last and how can it end?</li><li>What fees or compensation would you agree to, who is responsible for them and under what conditions?</li><li>How will the agent handle potential conflicts and explain your choices?</li></ul><p>Read the agreement before signing and ask about anything unclear. Fees and services belong in your own written terms; this page does not set them or promise that another party will pay.</p>')
    buying += section('inspection','Make room for the unglamorous questions.','<p>A nice kitchen is easy to notice. Ask how inspections, condition concerns, repair negotiations and contract deadlines would be handled. A real estate introduction does not verify the condition of a house, guarantee an offer or replace an independent inspection.</p><p>Keep identification, bank statements and other sensitive documents out of an introductory message. Ask the chosen professional which secure process to use when documents are actually needed. Wazoozie does not need them to help you make a first call.</p>')
    buying += faq([('Do I need to know everything before calling?','No. Share the area, timing and what you are unsure about. Ask what the first consultation includes and whether any agreement or fee applies.'),('Does Wazoozie select or book an agent for me?','No. The contacts below go directly to the named professionals. Wazoozie does not reserve appointments, distribute your inquiry or send it to an HVAC business.'),('Are these current license checks?','No. Public professional profiles establish the listed background, not current license status. Use <a href="https://www.pals.pa.gov/pages/search.html">Pennsylvania’s professional-license search</a> and confirm the appropriate state, brokerage and representation details directly.')])
    buying += section('sources','Meet the people, then choose.','<p>Read the source and contact information on each <a href="/real-estate-agents/">real estate profile</a>. This guide is general preparation, not legal, mortgage or tax advice. Your professionals should explain the rules and agreements that apply to your situation.</p>')
    render(buyer_path,'First-Time Home Buyer Conversations | Local Real Estate Agents','Buying your first home around Delco or Philadelphia? Prepare questions about representation, costs and inspections, then contact a listed real estate professional.','YOUR FIRST SET OF HOUSE KEYS','First home?<br><em>Start with good questions.</em>','A plain-English starting point for the conversation before the house hunt.','/real-estate-agents/','Real estate agents',buying,''.join(call_card(p,p['detail']) for p in agents),'<p>These professionals were recommended by Wazoozie’s owner. Their profiles link public business sources and explain what has not been independently checked. No transaction result, exclusive partnership or appointment is promised.</p>')

    # Make existing category pages better destinations, not keyword duplicates.
    def insert(path, content, marker, before=True):
        target = out/path.strip('/')/'index.html'
        s = target.read_text()
        assert marker in s, (path, marker)
        s = s.replace(marker, content+marker if before else marker+content, 1)
        if '/assets/service-intents.css' not in s:
            s = s.replace('</head>','<link rel="stylesheet" href="/assets/service-intents.css"></head>',1)
        target.write_text(s)

    def browse(title, cards):
        return '<section class="intent-browse"><h2>'+title+'</h2><div class="intent-route-grid">'+''.join('<a href="'+url+'"><h3>'+label+'</h3><p>'+copy+'</p><span>Take a look →</span></a>' for url,label,copy in cards)+'</div></section>'

    insert('/services/heating-cooling/',browse('What kind of comfort help do you need?',[(furnace_path,'Furnace not heating','Four safe checks and the details to give the office.'),('/services/boilers/','Boiler or radiator trouble','Gas and oil boiler service needs its own conversation.'),('/services/ductless-mini-splits/','One room needs attention','Explore room-by-room heating and cooling.'),('/services/replacement-estimates/','Planning a replacement','Compare the complete installation scope.')]),'<article class="prose">',False)
    insert('/services/electrical/',ELECTRICAL_TIPS+browse('Planning something bigger?',[(panel_path,'Electrical panel upgrades','Capacity, permits, downtime and the written proposal.'),('/businesses/ryan-dugan-electric/','Meet Ryan Dugan Electric','See published services, the working relationship and reviews.')]),'<article class="prose">',False)
    auto_content = browse('Start with the job, then choose the shop.',[(trans_path,'Transmission concerns in Eddystone','What to describe and ask before authorizing diagnostics.'),('/businesses/c-and-j-automotive-upper-chichester/','Maintenance, tires & repair inquiries','Meet C&J’s Upper Chichester location and confirm your vehicle.'),('/businesses/authority-auto-repair-glenolden/','Auto repair in Glenolden','Read Authority’s public contact sources before calling.')])
    insert('/auto-mechanics/',auto_content,'<div class="local-pro-grid">')
    insert('/real-estate-agents/',browse('Which chapter are you planning?',[(buyer_path,'Buying your first home','A plain-English guide to the first agent conversation.'),('#selling-questions','Getting ready to sell','Questions about preparation, pricing and written service terms.')]),'<div class="local-pro-grid">')
    insert('/real-estate-agents/',section('selling-questions','Selling? Start before the paint samples.','<p>Ask the professional how they would assess your property, explain a pricing recommendation and decide which preparation is worth discussing. Request the marketing scope, communication plan, fees and expected seller costs in writing. A proposed listing price is not a guaranteed sale price.</p><p>Tell them your timing and any linked purchase. Discuss who handles photos, showings, offers and negotiations, and which expenses need your approval. Choose a professional from the profiles above and confirm coverage for the property address directly.</p>'),'<section id="real-estate-questions" class="local-question-band">')

    # Direct contact in all auto and real estate cards, without creating a new intake.
    for path, group in [('/auto-mechanics/',[p for p in PEOPLE if p['category']=='automotive' and not p.get('vehiclewrap')]),('/real-estate-agents/',agents)]:
        target = out/path.strip('/')/'index.html'; s = target.read_text()
        for p in group:
            anchor = link('/businesses/'+p['slug']+'/', 'Meet '+p['name']+' →')
            assert anchor in s
            s = s.replace(anchor,anchor+'<div class="intent-actions">'+link('tel:'+p['tel'],'Call '+p['phone'],'btn outline')+'</div>',1)
        target.write_text(s)

    for path, new_path, label in [('/businesses/middletown-hvac/',furnace_path,'Furnace not heating? Four safe checks and service questions'),('/businesses/ryan-dugan-electric/',panel_path,'Planning a panel upgrade? Start here'),('/businesses/trans-man-transmissions-eddystone/',trans_path,'Prepare for a transmission-service conversation')]+[('/businesses/'+p['slug']+'/',buyer_path,'Buying your first home? Questions for the first conversation') for p in agents]:
        insert(path,'<section class="wrap intent-related"><h2>A useful place to start.</h2>'+link(new_path,label+' →')+'</section>','</main>')
    insert('/services/','<div class="wrap">'+browse('A closer look at common questions.',[(furnace_path,'Furnace repair & no-heat help','Simple checks and the diagnostic-visit conversation.'),(panel_path,'Electrical panel upgrade planning','Make the scope, responsibilities and downtime clear.')])+'</div>','</main>')
    insert('/local-help/','<div class="wrap">'+browse('A good question opens the right door.',[(furnace_path,'No heat at home?','Four simple checks, then a direct service connection.'),('/services/electrical/#simple-electrical-checks','Lights not working?','Start with switches, bulbs and safe breaker checks.'),(trans_path,'Car shifting differently?','Get ready for a transmission-service conversation.'),(buyer_path,'Buying your first home?','Meet the process and the people who can explain it.')] )+'</div>','</main>')

    for path, heading in [('/services/electrical/','Electrical repairs &amp; upgrades.<br><em>Ryan Dugan Electric.</em>'),('/auto-mechanics/','Auto repair around Delco.<br><em>Know who you’re calling.</em>'),('/real-estate-agents/','Local real estate agents.<br><em>Your next chapter starts here.</em>')]:
        target = out/path.strip('/')/'index.html'
        target.write_text(re.sub(r'<h1[^>]*>.*?</h1>','<h1>'+heading+'</h1>',target.read_text(),count=1,flags=re.S))
